{
  "$schema": "https://json.schemastore.org/package.json",
  "name": "@krishantt/opencode-go-usage",
  "version": "0.1.3",
  "type": "module",
  "description": "OpenCode TUI plugin: OpenCode Go usage limits plus burn-rate pacing warnings in the status bar",
  "keywords": [
    "opencode",
    "opencode-go",
    "opencode-plugin",
    "opencode-tui",
    "usage",
    "usage-limits",
    "quota",
    "pacing",
    "rate-limits"
  ],
  "license": "MIT",
  "author": "Krishant Timilsina",
  "repository": "github:krishantt/opencode-go-usage",
  "exports": {
    ".": "./index.ts",
    "./tui": "./tui.tsx"
  },
  "dependencies": {
    "@opencode/plugin": "latest"
  },
  "peerDependencies": {
    "@opentui/core": ">=0.6.6",
    "@opentui/solid": ">=0.6.6",
    "solid-js": ">=1.9.0"
  },
  "files": [
    "index.ts",
    "tui.tsx",
    "usage.ts"
  ],
  "scripts": {
    "test": "node --test",
    "typecheck": "tsc --noEmit"
  },
  "devDependencies": {
    "@types/node": "^24.0.0",
    "typescript": "^5.9.0"
  }
}
